async function rebuildFromExistingSegmentsEvidence(env, ts, cw, contract, curFin, options = {}) {
  const round2 = roundMoney2HalfAwayExact;
  const asNumberLocal = (v) => (v == null ? 0 : Number(v) || 0);
  const trimStr = (v) => (v == null ? '' : String(v).trim());

  const ib = curFin?.invoice_breakdown_json || null;
  const mode = String(ib?.mode || '').toUpperCase();
  const segs = Array.isArray(ib?.segments) ? ib.segments : null;
  if (mode !== 'SEGMENTS' || !segs || !segs.length) {
    throw new Error('NO_EXISTING_SEGMENTS_EVIDENCE');
  }

  const {
    outbox_id = null,
    write_now = false,
    hr_eff_flags = null,
    hr_preloaded_shifts = null,

    // ✅ NEW: HR weekly validation status (controls when we overwrite refs from import)
    hr_validation_status = null,
    hr_validation_reason_code = null,

    // ✅ allow caller to pass SQL policy (ctx.out_policy) to avoid REST
    policy_override = null
  } = (options && typeof options === 'object') ? options : {};

  const pc = payChargeFromContract(contract);
  const pay = pc?.pay || null;
  const chg = pc?.charge || null;
  const method = pc?.method || contract.pay_method_snapshot || null;
  if (!pay || !chg) throw new Error('CONTRACT_RATES_MISSING');

  // ✅ GLOBAL RULE: never allow weekly to be READY_* unless authorised
  const isAuthorised = !!(ts && ts.authorised_at_server);
  const processing_status = (!isAuthorised) ? 'PENDING_AUTH' : 'READY_FOR_INVOICE';

  // ✅ Determine whether we should override segment ref_num from imported HealthRoster shifts.
  const boolishLocal = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on' || s === 't');
  };

  const hrValidationRequired =
    boolishLocal(hr_eff_flags?.client_hr_validation_required) ||
    boolishLocal(hr_eff_flags?.hr_validation_required_for_invoice) ||
    false;

  const valStatusU = String(hr_validation_status || '').trim().toUpperCase();
  const valReasonU = String(hr_validation_reason_code || '').trim().toUpperCase();

  const isValidatedOk =
    (valStatusU === 'VALIDATION_OK' || valStatusU === 'OVERRIDDEN' || valStatusU === 'OVERRIDE');

  const isWeeklyHrValidation =
    (!valReasonU) ? true : valReasonU.includes('HEALTHROSTER_WEEKLY');

  const useImportRefs = !!(hrValidationRequired && isValidatedOk && isWeeklyHrValidation);

  const parseUtcMs = (v) => {
    if (v == null) return null;
    let s = String(v).trim();
    if (!s) return null;
    if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}/.test(s) && !s.includes('T')) {
      s = s.replace(' ', 'T');
    }
    const d = new Date(s);
    if (Number.isNaN(d.getTime())) return null;
    return d.getTime();
  };

  const hrRefByKey = new Map();   // `${date}|${startMs}|${endMs}` -> ref_num
  const hrListByDate = new Map(); // date -> [{startMs,endMs,ref_num}]
  if (useImportRefs && Array.isArray(hr_preloaded_shifts) && hr_preloaded_shifts.length) {
    for (const sh of hr_preloaded_shifts) {
      const ss = String(sh?.source_system || '').trim().toUpperCase();
      if (ss !== 'HEALTHROSTER') continue;

      const d = sh?.work_date ? String(sh.work_date).slice(0, 10) : '';
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;

      const ref = (sh?.ref_num != null) ? String(sh.ref_num).trim() : '';
      if (!ref) continue;

      const sMs = parseUtcMs(sh?.start_utc);
      const eMs = parseUtcMs(sh?.end_utc);
      if (sMs == null || eMs == null) continue;

      const k = `${d}|${sMs}|${eMs}`;
      if (!hrRefByKey.has(k)) hrRefByKey.set(k, ref);

      if (!hrListByDate.has(d)) hrListByDate.set(d, []);
      hrListByDate.get(d).push({ startMs: sMs, endMs: eMs, ref_num: ref });
    }
  }

  // ✅ Policy snapshot: prefer SQL policy_override; fallback to getPolicyCached only if missing
  let policy_snapshot_json = {};
  if (policy_override && typeof policy_override === 'object') {
    policy_snapshot_json = policy_override;
  } else {
    try {
      const we = String(ts.week_ending_date || cw.week_ending_date || '');
      policy_snapshot_json =
        (contract.client_id && we && typeof getPolicyCached === 'function')
          ? (await getPolicyCached(contract.client_id, we, {
              contract_id: contract.id, timesheet_id: ts.timesheet_id, workflow: 'WEEKLY'
            }))
          : {};
      if (!policy_snapshot_json || typeof policy_snapshot_json !== 'object') policy_snapshot_json = {};
    } catch {
      policy_snapshot_json = {};
    }
  }

  // ─────────────────────────────────────────────────────────────
  // ✅ Option A expense rollup (travel+accom+other, fallback to expenses_*)
  // ─────────────────────────────────────────────────────────────
  const catPay = round2(
    asNumberLocal(curFin?.travel_pay_ex_vat ?? 0) +
    asNumberLocal(curFin?.accommodation_pay_ex_vat ?? 0) +
    asNumberLocal(curFin?.other_pay_ex_vat ?? 0)
  );
  const catChg = round2(
    asNumberLocal(curFin?.travel_charge_ex_vat ?? 0) +
    asNumberLocal(curFin?.accommodation_charge_ex_vat ?? 0) +
    asNumberLocal(curFin?.other_charge_ex_vat ?? 0)
  );

  const expPayEff = round2((catPay !== 0) ? catPay : asNumberLocal(curFin?.expenses_pay_ex_vat ?? 0));
  const expChgEff = round2((catChg !== 0) ? catChg : asNumberLocal(curFin?.expenses_charge_ex_vat ?? 0));

  const milUnits = round2(asNumberLocal(curFin?.mileage_units ?? 0));
  const milPay = round2(asNumberLocal(curFin?.mileage_pay_ex_vat ?? 0));
  const milChg = round2(asNumberLocal(curFin?.mileage_charge_ex_vat ?? 0));

  // Preserve additional (wage-like) fields from current snapshot
  const addlUnitsJson =
    (curFin?.additional_units_json && typeof curFin.additional_units_json === 'object')
      ? curFin.additional_units_json
      : {};

  const addlPay = round2(asNumberLocal(curFin?.additional_pay_ex_vat ?? 0));
  const addlChg = round2(asNumberLocal(curFin?.additional_charge_ex_vat ?? 0));
  const addlMar = round2(asNumberLocal(curFin?.additional_margin_ex_vat ?? (addlChg - addlPay)));

  const staleReason = (curFin && curFin.stale_reason != null) ? String(curFin.stale_reason) : '';
  const dropUnlockedBecauseCantRebuildTruth = (staleReason === 'IMPORT_CANCEL_DETACH');

  let sumDay = 0, sumNight = 0, sumSat = 0, sumSun = 0, sumBh = 0;
  let segPaySum = 0;    // pay totals must respect exclude_from_pay
  let segChgSum = 0;

  const nextSegments = [];
  for (const s of segs) {
    if (!s || typeof s !== 'object') continue;

    const invLock = trimStr(s.invoice_locked_invoice_id);
    const isLocked = invLock !== '';

    if (dropUnlockedBecauseCantRebuildTruth && !isLocked) {
      continue;
    }

    const hDay   = asNumberLocal(s.hours_day);
    const hNight = asNumberLocal(s.hours_night);
    const hSat   = asNumberLocal(s.hours_sat);
    const hSun   = asNumberLocal(s.hours_sun);
    const hBh    = asNumberLocal(s.hours_bh);

    sumDay += hDay; sumNight += hNight; sumSat += hSat; sumSun += hSun; sumBh += hBh;

    const excludeFromPay = !!s.exclude_from_pay;

    if (isLocked) {
      // ✅ Locked segment evidence is immutable: do NOT change ref_num or amounts.
      const payExLocked = asNumberLocal(s.pay_amount);
      const chgExLocked = asNumberLocal(s.charge_amount);

      if (!excludeFromPay) segPaySum += payExLocked;
      segChgSum += chgExLocked;

      nextSegments.push(s);
      continue;
    }

    // Unlocked segment: recalc amounts from stored hours using current contract rates.
    const payEx = round2(
      hDay   * asNumberLocal(pay.day) +
      hNight * asNumberLocal(pay.night) +
      hSat   * asNumberLocal(pay.sat) +
      hSun   * asNumberLocal(pay.sun) +
      hBh    * asNumberLocal(pay.bh)
    );

    const chgEx = round2(
      hDay   * asNumberLocal(chg.day) +
      hNight * asNumberLocal(chg.night) +
      hSat   * asNumberLocal(chg.sat) +
      hSun   * asNumberLocal(chg.sun) +
      hBh    * asNumberLocal(chg.bh)
    );

    if (!excludeFromPay) segPaySum += payEx;
    segChgSum += chgEx;

    // ✅ Import ref propagation (unlocked only)
    let nextRefNum = (s.ref_num != null) ? String(s.ref_num).trim() : '';
    if (useImportRefs) {
      const dateYmd = (s?.date != null) ? String(s.date).slice(0, 10) : '';
      const sMs = parseUtcMs(s?.start_utc || s?.startUtc || null);
      const eMs = parseUtcMs(s?.end_utc || s?.endUtc || null);

      let hrRef = null;
      if (dateYmd && sMs != null && eMs != null) {
        const k2 = `${dateYmd}|${sMs}|${eMs}`;
        hrRef = hrRefByKey.get(k2) || null;
      }

      if (!hrRef && dateYmd && hrListByDate.has(dateYmd)) {
        const arr = hrListByDate.get(dateYmd) || [];
        const uniq = new Set(arr.map(x => String(x.ref_num || '').trim()).filter(Boolean));
        if (uniq.size === 1) hrRef = Array.from(uniq)[0];
      }

      nextRefNum = hrRef ? String(hrRef) : '';
    }

    nextSegments.push({
      ...s,
      ref_num: nextRefNum ? nextRefNum : null,
      pay_amount: payEx,
      charge_amount: chgEx
    });
  }

  segPaySum = round2(segPaySum);
  segChgSum = round2(segChgSum);

  // ✅ Totals include non-segment amounts (additional + expenses + mileage)
  const nonsegPay = round2(addlPay + expPayEff + milPay);
  const nonsegChg = round2(addlChg + expChgEff + milChg);

  const totalPayEx = round2(segPaySum + nonsegPay);
  const totalChgEx = round2(segChgSum + nonsegChg);

  // ✅ ERNI-aware margin (PAYE only; wage pay only; NEVER on expenses/mileage)
  const pol = (policy_snapshot_json && typeof policy_snapshot_json === 'object') ? policy_snapshot_json : {};
  const applyTo = String(pol.apply_erni_to || 'PAYE_ONLY').toUpperCase();
  const erniPctRaw = Number(pol.erni_pct ?? 0);

  let erniMult = 1;
  if (Number.isFinite(erniPctRaw) && erniPctRaw > 0) {
    const p = erniPctRaw > 1 ? (erniPctRaw / 100) : erniPctRaw;
    erniMult = 1 + p;
  }

  const payMethodU = String(method || '').toUpperCase();

  const erniApplies =
    (payMethodU === 'PAYE') &&
    (applyTo === 'ALL' || applyTo === 'PAYE_ONLY');

  const wagePay = round2(segPaySum + addlPay);
  const reimbPay = round2(expPayEff + milPay);

  const wageCost = round2(erniApplies ? (wagePay * erniMult) : wagePay);
  const payCostEx = round2(wageCost + reimbPay);

  const marginEx = round2(totalChgEx - payCostEx);

  // ✅ Non-seg margin: ERNI only on additional pay, never on expenses/mileage
  const addlWageCost = round2(erniApplies ? (addlPay * erniMult) : addlPay);
  const nonsegPayCost = round2(addlWageCost + reimbPay);
  const nonsegMar = round2(nonsegChg - nonsegPayCost);

  const hours_day   = round2(sumDay);
  const hours_night = round2(sumNight);
  const hours_sat   = round2(sumSat);
  const hours_sun   = round2(sumSun);
  const hours_bh    = round2(sumBh);
  const total_hours = round2(hours_day + hours_night + hours_sat + hours_sun + hours_bh);

  const priorUnits =
    (ib && typeof ib === 'object' && ib.additional && typeof ib.additional === 'object' && ib.additional.units && typeof ib.additional.units === 'object')
      ? ib.additional.units
      : addlUnitsJson;

  const snapshot = {
    timesheet_id: ts.timesheet_id,
    timesheet_version: ts.version || 1,

    basis: curFin?.basis || 'CONTRACT_WEEKLY',
    candidate_id: contract.candidate_id || null,
    client_id: contract.client_id || null,
    role: contract.role || null,
    band: contract.band || null,
    pay_method: method,

    policy_snapshot_json,
    rate_source_refs_json: { mode: 'CONTRACT_RATES_JSON', contract_id: contract.id || null },

    hours_day,
    hours_night,
    hours_sat,
    hours_sun,
    hours_bh,
    total_hours,

    pay_day: pay.day, pay_night: pay.night, pay_sat: pay.sat, pay_sun: pay.sun, pay_bh: pay.bh,
    charge_day: chg.day, charge_night: chg.night, charge_sat: chg.sat, charge_sun: chg.sun, charge_bh: chg.bh,

    additional_units_json: addlUnitsJson,
    additional_pay_ex_vat: addlPay,
    additional_charge_ex_vat: addlChg,
    additional_margin_ex_vat: addlMar,

    total_pay_ex_vat: totalPayEx,
    total_charge_ex_vat: totalChgEx,
    margin_ex_vat: marginEx,

    expenses_pay_ex_vat: expPayEff,
    expenses_charge_ex_vat: expChgEff,
    expenses_description: curFin?.expenses_description ?? null,
    expenses_evidence_r2_key: curFin?.expenses_evidence_r2_key ?? null,
    expenses_evidence_manifest: curFin?.expenses_evidence_manifest ?? null,

    travel_pay_ex_vat: round2(asNumberLocal(curFin?.travel_pay_ex_vat ?? 0)),
    travel_charge_ex_vat: round2(asNumberLocal(curFin?.travel_charge_ex_vat ?? 0)),
    accommodation_pay_ex_vat: round2(asNumberLocal(curFin?.accommodation_pay_ex_vat ?? 0)),
    accommodation_charge_ex_vat: round2(asNumberLocal(curFin?.accommodation_charge_ex_vat ?? 0)),
    other_pay_ex_vat: round2(asNumberLocal(curFin?.other_pay_ex_vat ?? 0)),
    other_charge_ex_vat: round2(asNumberLocal(curFin?.other_charge_ex_vat ?? 0)),

    mileage_units: milUnits,
    mileage_pay_ex_vat: milPay,
    mileage_charge_ex_vat: milChg,
    mileage_evidence_r2_key: curFin?.mileage_evidence_r2_key ?? null,
    mileage_evidence_manifest: curFin?.mileage_evidence_manifest ?? null,
    mileage_pay_rate: curFin?.mileage_pay_rate ?? null,
    mileage_charge_rate: curFin?.mileage_charge_rate ?? null,

    candidate_assignment: (contract.candidate_id ? 'ASSIGNED' : 'UNASSIGNED'),
    processing_status,

    invoice_breakdown_json: {
      mode: 'SEGMENTS',
      segments: nextSegments,
      additional: {
        units: priorUnits || {},
        pay_ex_vat: nonsegPay,
        charge_ex_vat: nonsegChg,
        margin_ex_vat: nonsegMar
      },
      totals: {
        total_pay_ex_vat: totalPayEx,
        total_charge_ex_vat: totalChgEx,
        margin_ex_vat: marginEx
      }
    },

    external_source_rows_json: curFin?.external_source_rows_json || {}
  };

  if (typeof enrichTsfinWithHrCrosscheck === 'function') {
    try { await enrichTsfinWithHrCrosscheck(env, ts, snapshot, hr_eff_flags || null, hr_preloaded_shifts || null); } catch {}
  }

  if (write_now) {
    if (!outbox_id) throw new Error('rebuildFromExistingSegmentsEvidence: write_now requires options.outbox_id');
    const wr = await rpcTsfinWriteSnapshotsAndComplete(env, {
      rows: [{ outbox_id, timesheet_id: ts.timesheet_id, snapshot }]
    });
    return { ok: true, snapshot, write: wr };
  }

  return { ok: true, snapshot };
}

