    asNumberLocal(curFin?.accommodation_charge_ex_vat ?? 0) +
    asNumberLocal(curFin?.other_charge_ex_vat ?? 0)
  );

  const expPayEff = round2((catPay !== 0) ? catPay : asNumberLocal(curFin?.expenses_pay_ex_vat ?? 0));
  const expChgEff = round2((catChg !== 0) ? catChg : asNumberLocal(curFin?.expenses_charge_ex_vat ?? 0));

  const milUnits = round2(asNumberLocal(curFin?.mileage_units ?? 0));
  const milPay = round2(asNumberLocal(curFin?.mileage_pay_ex_vat ?? 0));
  const milChg = round2(asNumberLocal(curFin?.mileage_charge_ex_vat ?? 0));

  // Preserve additional (wage-like) fields from current snapshot
  const addlUnitsJson =
    (curFin?.additional_units_json && typeof curFin.additional_units_json === 'object')
      ? curFin.additional_units_json
      : {};

  const addlPay = round2(asNumberLocal(curFin?.additional_pay_ex_vat ?? 0));
  const addlChg = round2(asNumberLocal(curFin?.additional_charge_ex_vat ?? 0));
  const addlMar = round2(asNumberLocal(curFin?.additional_margin_ex_vat ?? (addlChg - addlPay)));

  const staleReason = (curFin && curFin.stale_reason != null) ? String(curFin.stale_reason) : '';
  const dropUnlockedBecauseCantRebuildTruth = (staleReason === 'IMPORT_CANCEL_DETACH');

  let sumDay = 0, sumNight = 0, sumSat = 0, sumSun = 0, sumBh = 0;
  let segPaySum = 0;    // pay totals must respect exclude_from_pay
  let segChgSum = 0;

  const nextSegments = [];
  for (const s of segs) {
    if (!s || typeof s !== 'object') continue;

    const invLock = trimStr(s.invoice_locked_invoice_id);
    const isLocked = invLock !== '';

    if (dropUnlockedBecauseCantRebuildTruth && !isLocked) {
      continue;
    }

    const hDay   = asNumberLocal(s.hours_day);
    const hNight = asNumberLocal(s.hours_night);
    const hSat   = asNumberLocal(s.hours_sat);
    const hSun   = asNumberLocal(s.hours_sun);
    const hBh    = asNumberLocal(s.hours_bh);

    sumDay += hDay; sumNight += hNight; sumSat += hSat; sumSun += hSun; sumBh += hBh;

    const excludeFromPay = !!s.exclude_from_pay;

    if (isLocked) {
      // ✅ Locked segment evidence is immutable: do NOT change ref_num or amounts.
      const payExLocked = asNumberLocal(s.pay_amount);
      const chgExLocked = asNumberLocal(s.charge_amount);

      if (!excludeFromPay) segPaySum += payExLocked;
      segChgSum += chgExLocked;

      nextSegments.push(s);
      continue;
    }

    // Unlocked segment: recalc amounts from stored hours using current contract rates.
    const payEx = round2(
      hDay   * asNumberLocal(pay.day) +
      hNight * asNumberLocal(pay.night) +
      hSat   * asNumberLocal(pay.sat) +
      hSun   * asNumberLocal(pay.sun) +
      hBh    * asNumberLocal(pay.bh)
    );

    const chgEx = round2(
      hDay   * asNumberLocal(chg.day) +
      hNight * asNumberLocal(chg.night) +
      hSat   * asNumberLocal(chg.sat) +
      hSun   * asNumberLocal(chg.sun) +
      hBh    * asNumberLocal(chg.bh)
    );

    if (!excludeFromPay) segPaySum += payEx;
    segChgSum += chgEx;

    // ✅ Import ref propagation (unlocked only)
    let nextRefNum = (s.ref_num != null) ? String(s.ref_num).trim() : '';
    if (useImportRefs) {
      const dateYmd = (s?.date != null) ? String(s.date).slice(0, 10) : '';
      const sMs = parseUtcMs(s?.start_utc || s?.startUtc || null);
      const eMs = parseUtcMs(s?.end_utc || s?.endUtc || null);

      let hrRef = null;
      if (dateYmd && sMs != null && eMs != null) {
        const k2 = `${dateYmd}|${sMs}|${eMs}`;
        hrRef = hrRefByKey.get(k2) || null;
      }

      if (!hrRef && dateYmd && hrListByDate.has(dateYmd)) {
        const arr = hrListByDate.get(dateYmd) || [];
        const uniq = new Set(arr.map(x => String(x.ref_num || '').trim()).filter(Boolean));
        if (uniq.size === 1) hrRef = Array.from(uniq)[0];
      }

      nextRefNum = hrRef ? String(hrRef) : '';
    }

    nextSegments.push({
      ...s,
      ref_num: nextRefNum ? nextRefNum : null,
      pay_amount: payEx,
      charge_amount: chgEx
    });
  }

  segPaySum = round2(segPaySum);
  segChgSum = round2(segChgSum);

  // ✅ Totals include non-segment amounts (additional + expenses + mileage)
  const nonsegPay = round2(addlPay + expPayEff + milPay);
  const nonsegChg = round2(addlChg + expChgEff + milChg);

  const totalPayEx = round2(segPaySum + nonsegPay);
  const totalChgEx = round2(segChgSum + nonsegChg);

  // ✅ ERNI-aware margin (PAYE only; wage pay only; NEVER on expenses/mileage)
  const pol = (policy_snapshot_json && typeof policy_snapshot_json === 'object') ? policy_snapshot_json : {};
  const applyTo = String(pol.apply_erni_to || 'PAYE_ONLY').toUpperCase();
  const erniPctRaw = Number(pol.erni_pct ?? 0);

  let erniMult = 1;
  if (Number.isFinite(erniPctRaw) && erniPctRaw > 0) {
    const p = erniPctRaw > 1 ? (erniPctRaw / 100) : erniPctRaw;
    erniMult = 1 + p;
  }

  const payMethodU = String(method || '').toUpperCase();

  const erniApplies =
    (payMethodU === 'PAYE') &&
    (applyTo === 'ALL' || applyTo === 'PAYE_ONLY');

  const wagePay = round2(segPaySum + addlPay);
  const reimbPay = round2(expPayEff + milPay);

  const wageCost = round2(erniApplies ? (wagePay * erniMult) : wagePay);
  const payCostEx = round2(wageCost + reimbPay);

  const marginEx = round2(totalChgEx - payCostEx);

  // ✅ Non-seg margin: ERNI only on additional pay, never on expenses/mileage
  const addlWageCost = round2(erniApplies ? (addlPay * erniMult) : addlPay);
  const nonsegPayCost = round2(addlWageCost + reimbPay);
  const nonsegMar = round2(nonsegChg - nonsegPayCost);

  const hours_day   = round2(sumDay);
  const hours_night = round2(sumNight);
  const hours_sat   = round2(sumSat);
  const hours_sun   = round2(sumSun);
  const hours_bh    = round2(sumBh);
  const total_hours = round2(hours_day + hours_night + hours_sat + hours_sun + hours_bh);

  const priorUnits =
    (ib && typeof ib === 'object' && ib.additional && typeof ib.additional === 'object' && ib.additional.units && typeof ib.additional.units === 'object')
      ? ib.additional.units
      : addlUnitsJson;

  const snapshot = {
    timesheet_id: ts.timesheet_id,
    timesheet_version: ts.version || 1,

    basis: curFin?.basis || 'CONTRACT_WEEKLY',
    candidate_id: contract.candidate_id || null,
    client_id: contract.client_id || null,
    role: contract.role || null,
    band: contract.band || null,
    pay_method: method,

    policy_snapshot_json,
    rate_source_refs_json: { mode: 'CONTRACT_RATES_JSON', contract_id: contract.id || null },

    hours_day,
    hours_night,
    hours_sat,
    hours_sun,
    hours_bh,
    total_hours,

    pay_day: pay.day, pay_night: pay.night, pay_sat: pay.sat, pay_sun: pay.sun, pay_bh: pay.bh,
    charge_day: chg.day, charge_night: chg.night, charge_sat: chg.sat, charge_sun: chg.sun, charge_bh: chg.bh,

    additional_units_json: addlUnitsJson,
    additional_pay_ex_vat: addlPay,
    additional_charge_ex_vat: addlChg,
    additional_margin_ex_vat: addlMar,

    total_pay_ex_vat: totalPayEx,
    total_charge_ex_vat: totalChgEx,
    margin_ex_vat: marginEx,

    expenses_pay_ex_vat: expPayEff,
    expenses_charge_ex_vat: expChgEff,
    expenses_description: curFin?.expenses_description ?? null,
    expenses_evidence_r2_key: curFin?.expenses_evidence_r2_key ?? null,
    expenses_evidence_manifest: curFin?.expenses_evidence_manifest ?? null,

    travel_pay_ex_vat: round2(asNumberLocal(curFin?.travel_pay_ex_vat ?? 0)),
    travel_charge_ex_vat: round2(asNumberLocal(curFin?.travel_charge_ex_vat ?? 0)),
    accommodation_pay_ex_vat: round2(asNumberLocal(curFin?.accommodation_pay_ex_vat ?? 0)),
    accommodation_charge_ex_vat: round2(asNumberLocal(curFin?.accommodation_charge_ex_vat ?? 0)),
    other_pay_ex_vat: round2(asNumberLocal(curFin?.other_pay_ex_vat ?? 0)),
    other_charge_ex_vat: round2(asNumberLocal(curFin?.other_charge_ex_vat ?? 0)),

    mileage_units: milUnits,
    mileage_pay_ex_vat: milPay,
    mileage_charge_ex_vat: milChg,
    mileage_evidence_r2_key: curFin?.mileage_evidence_r2_key ?? null,
    mileage_evidence_manifest: curFin?.mileage_evidence_manifest ?? null,
    mileage_pay_rate: curFin?.mileage_pay_rate ?? null,
    mileage_charge_rate: curFin?.mileage_charge_rate ?? null,

    candidate_assignment: (contract.candidate_id ? 'ASSIGNED' : 'UNASSIGNED'),
    processing_status,

    invoice_breakdown_json: {
      mode: 'SEGMENTS',
      segments: nextSegments,
      additional: {
        units: priorUnits || {},
        pay_ex_vat: nonsegPay,
        charge_ex_vat: nonsegChg,
        margin_ex_vat: nonsegMar
      },
      totals: {
        total_pay_ex_vat: totalPayEx,
        total_charge_ex_vat: totalChgEx,
        margin_ex_vat: marginEx
      }
    },

    external_source_rows_json: curFin?.external_source_rows_json || {}
  };

  if (typeof enrichTsfinWithHrCrosscheck === 'function') {
    try { await enrichTsfinWithHrCrosscheck(env, ts, snapshot, hr_eff_flags || null, hr_preloaded_shifts || null); } catch {}
  }

  if (write_now) {
    if (!outbox_id) throw new Error('rebuildFromExistingSegmentsEvidence: write_now requires options.outbox_id');
    const wr = await rpcTsfinWriteSnapshotsAndComplete(env, {
      rows: [{ outbox_id, timesheet_id: ts.timesheet_id, snapshot }]
    });
    return { ok: true, snapshot, write: wr };
  }

  return { ok: true, snapshot };
}

hunks.before:
async function buildNhspWeeklySnapshot(
  env,
  ts,
  contract,
  shifts,
  nhspImportId,
  basis = 'NHSP',
  getPolicyCached,
  curFin,
  options = {}
) {
  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const asNumberLocal = (v) => (v == null ? 0 : Number(v) || 0);

  const {
    outbox_id = null,
    write_now = false,
    // optional HR enrich inputs (so snapshot contains hr_crosscheck_* before write)
    hr_eff_flags = null,
    hr_preloaded_shifts = null,

    // ✅ allow caller to pass SQL policy (ctx.out_policy) to avoid REST
    policy_override = null,

    // ✅ NEW: validation state (so ref_num can be overridden ONLY after validation OK)
    hr_validation_status = null,
    hr_validation_reason_code = null
  } = (options && typeof options === 'object') ? options : {};

  const hasPolicyOverride = !!(policy_override && typeof policy_override === 'object');

  const pc  = payChargeFromContract(contract);
  const pay = pc?.pay || null;
  const chg = pc?.charge || null;
  const method = pc?.method || contract?.pay_method_snapshot || contract?.pay_method || null;

  if (!pay || !chg) return { ok: false, reason: 'CONTRACT_RATES_MISSING' };

  const candidate_id = contract.candidate_id || null;
  const client_id    = contract.client_id   || null;

  // ---- Policy helper ----
  // If policy_override is provided, we do not need getPolicyCached at all.
  if (!hasPolicyOverride && typeof getPolicyCached !== 'function') {
    throw new Error('buildNhspWeeklySnapshot: getPolicyCached must be provided (or pass options.policy_override)');
  }

  // ─────────────────────────────────────────────────────────────
  // ✅ Stable segment identity helpers (NHSP weekly)
  //
  // Fixes delayed segment corruption by:
  // - generating deterministic segment_id from immutable shift attributes (not sh.id)
  // - preserving per-segment controls by mapping old→new using the same fingerprint
  //
  // NOTE: We intentionally do NOT include ref_num in identity (it may be amended later).
  // ─────────────────────────────────────────────────────────────
  const _normStr = (v) => (v == null ? '' : String(v).trim());
  const _normNumInt = (v, d = 0) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };

  // FNV-1a 32-bit hash (deterministic, fast, no async crypto)
  const _hash32 = (s) => {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193);
    }
    return (h >>> 0).toString(16).padStart(8, '0');
  };

  const _stableKeyFromParts = (dateYmd, startUtc, endUtc, breakMins, requestId) => {
    const d = _normStr(dateYmd);
    const s = _normStr(startUtc);
    const e = _normStr(endUtc);
    const b = _normNumInt(breakMins ?? 0, 0);
    const r = _normStr(requestId); // optional but stable if present; safe to include
    // If we have no useful timestamps, return empty => will fall back to legacy segment_id matching only.
    if (!d && !s && !e) return '';
    return `d:${d}|s:${s}|e:${e}|b:${b}|r:${r}`;
  };

  const _stableKeyFromShift = (sh) => {
    if (!sh || typeof sh !== 'object') return '';
    const workDate = _normStr(sh.work_date);
    const startUtc = _normStr(sh.start_utc);
    const endUtc   = _normStr(sh.end_utc);
    const breakM   = _normNumInt(sh.break_mins ?? sh.break_minutes ?? 0, 0);
    const reqId    = _normStr(sh.hr_request_id || sh.request_id || '');
    return _stableKeyFromParts(workDate, startUtc, endUtc, breakM, reqId);
  };

  const _stableKeyFromExistingSegment = (s) => {
    if (!s || typeof s !== 'object') return '';
    const dateYmd = _normStr(s.date);
    const startUtc = _normStr(s.start_utc || s.start_iso || '');
    const endUtc   = _normStr(s.end_utc || s.end_iso || '');
    const breakM   = _normNumInt(s.break_mins ?? s.break_minutes ?? 0, 0);
    const reqId    = _normStr(s.request_id || '');
    return _stableKeyFromParts(dateYmd, startUtc, endUtc, breakM, reqId);
  };

  const _stableSegId = (tsId, stableKey) => {
    const k = _normStr(stableKey);
    if (!k) return `nhsp:${tsId}:unknown`;
    return `nhsp:${tsId}:${_hash32(k)}`;
  };

  // ─────────────────────────────────────────────────────────────
  // ✅ HR import ref override (only after validation OK/OVERRIDDEN)
  // Applies when HR validation is required and the validation context is weekly HR.
  // ─────────────────────────────────────────────────────────────
  const boolishLocal = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on' || s === 't');
  };

  const hrValidationRequired =
    boolishLocal(hr_eff_flags?.client_hr_validation_required) ||
    boolishLocal(hr_eff_flags?.hr_validation_required_for_invoice) ||
    false;

  const valStatusU = String(hr_validation_status || '').trim().toUpperCase();
  const valReasonU = String(hr_validation_reason_code || '').trim().toUpperCase();

  const isValidatedOk =
    (valStatusU === 'VALIDATION_OK' || valStatusU === 'OVERRIDDEN' || valStatusU === 'OVERRIDE');

  const isWeeklyHrValidation =
    (!valReasonU) ? true : valReasonU.includes('HEALTHROSTER_WEEKLY');

  const useImportRefs = !!(hrValidationRequired && isValidatedOk && isWeeklyHrValidation);

  const parseUtcMs = (v) => {
    if (v == null) return null;
    let s = String(v).trim();
    if (!s) return null;
    // tolerate "YYYY-MM-DD HH:MM:SS+00"
    if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}/.test(s) && !s.includes('T')) {
      s = s.replace(' ', 'T');
    }
    const d = new Date(s);
    if (Number.isNaN(d.getTime())) return null;
    return d.getTime();
  };

  // `${date}|${startMs}|${endMs}` -> ref_num
  const hrRefByKey = new Map();
  const hrListByDate = new Map();
  if (useImportRefs && Array.isArray(hr_preloaded_shifts) && hr_preloaded_shifts.length) {
    for (const sh of hr_preloaded_shifts) {
      const ss = String(sh?.source_system || '').trim().toUpperCase();
      if (ss !== 'HEALTHROSTER') continue;

      const d = sh?.work_date ? String(sh.work_date).slice(0, 10) : '';
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;

      const ref = (sh?.ref_num != null) ? String(sh.ref_num).trim() : '';
      if (!ref) continue;

      const sMs = parseUtcMs(sh?.start_utc);
      const eMs = parseUtcMs(sh?.end_utc);
      if (sMs == null || eMs == null) continue;

      const k = `${d}|${sMs}|${eMs}`;
      if (!hrRefByKey.has(k)) hrRefByKey.set(k, ref);

      if (!hrListByDate.has(d)) hrListByDate.set(d, []);
      hrListByDate.get(d).push({ startMs: sMs, endMs: eMs, ref_num: ref });
    }
  }

  // ─────────────────────────────────────────────────────────────
  // Preserve existing TSFIN evidence:
  // - meta controls for unlocked recompute (exclude_from_pay, invoice_target_week_start)
  // - FULL locked segment objects (invoice_locked_invoice_id != null/empty) to preserve evidence exactly
  // ─────────────────────────────────────────────────────────────
  const preservedByKey = new Map();
  const preservedByLegacyId = new Map();
  const preservedByNhspShiftId = new Map();
  const preservedByExternalRowKey = new Map();

  const lockedSegByKey = new Map();
  const lockedSegByLegacyId = new Map();
  const lockedSegByNhspShiftId = new Map();
  const lockedSegByExternalRowKey = new Map();
  const lockedSegsAll = [];

  function btrim(s) { return String(s).trim(); }
  function nullif(a, b) { return (a === b) ? null : a; }

  const _segUniqKey = (s) => {
    const sid = (s && s.segment_id != null) ? String(s.segment_id).trim() : '';
    if (sid) return `sid:${sid}`;
    const nid = (s && s.nhsp_shift_id != null) ? String(s.nhsp_shift_id).trim() : '';
    if (nid) return `nhsp:${nid}`;
    const ek  = (s && s.external_row_key != null) ? String(s.external_row_key).trim() : '';
    if (ek) return `ext:${ek}`;
    const sk  = _stableKeyFromExistingSegment(s);
    if (sk) return `stk:${sk}`;
    return `obj:${btrim(JSON.stringify(s || {})).slice(0, 200)}`;
  };

  try {
    const ib = curFin?.invoice_breakdown_json || null;
    const mode = String(ib?.mode || '').toUpperCase();
    const segs = Array.isArray(ib?.segments) ? ib.segments : null;

    if (mode === 'SEGMENTS' && segs) {
      for (const s of segs) {
        const segment_id = (s && s.segment_id != null) ? String(s.segment_id) : null;

        const invLockRaw = (s && s.invoice_locked_invoice_id != null) ? String(s.invoice_locked_invoice_id) : '';
        const invLockTrim = btrim(invLockRaw);
        const isLocked = invLockTrim !== '';

        const meta = {
          exclude_from_pay:
            (typeof s.exclude_from_pay === 'boolean') ? s.exclude_from_pay : undefined,
          invoice_target_week_start:
            (s.invoice_target_week_start != null) ? String(s.invoice_target_week_start) : undefined,
          invoice_locked_invoice_id:
            (invLockTrim !== '') ? invLockTrim : undefined
        };

        if (segment_id) preservedByLegacyId.set(segment_id, meta);

        const key = _stableKeyFromExistingSegment(s);
        if (key) preservedByKey.set(key, meta);

        const nhspShiftId = (s && s.nhsp_shift_id != null) ? String(s.nhsp_shift_id).trim() : '';
        const extKey = (s && s.external_row_key != null) ? String(s.external_row_key).trim() : '';
        if (nhspShiftId) preservedByNhspShiftId.set(nhspShiftId, meta);
        if (extKey) preservedByExternalRowKey.set(extKey, meta);

        if (isLocked) {
          lockedSegsAll.push(s);
          if (segment_id) lockedSegByLegacyId.set(segment_id, s);
          if (key) lockedSegByKey.set(key, s);
          if (nhspShiftId) lockedSegByNhspShiftId.set(nhspShiftId, s);
          if (extKey) lockedSegByExternalRowKey.set(extKey, s);
        }
      }
    }
  } catch {}

  const staleReason = (curFin && curFin.stale_reason != null) ? String(curFin.stale_reason) : '';

  const shiftsArr = Array.isArray(shifts) ? shifts : [];

  const normaliseImportedSourceSystem = (value) => {
    const raw = String(value || '').trim().toUpperCase();
    if (!raw) return null;
    if (raw === 'HEALTHROSTER' || raw === 'HR' || raw === 'HEALTH_ROSTER') return 'HEALTHROSTER';
    if (raw === 'NHSP') return 'NHSP';
    return raw;
  };

  const resolveImportedWeeklyEvidenceSource = (sourceShifts, basisForEvidence) => {
    const sourceSystems = [];
    for (const sh of Array.isArray(sourceShifts) ? sourceShifts : []) {
      const source = normaliseImportedSourceSystem(sh?.source_system);
      if (source && !sourceSystems.includes(source)) sourceSystems.push(source);
    }

    if (!sourceSystems.length) {
      const basisSource = normaliseImportedSourceSystem(basisForEvidence);
      if (basisSource) sourceSystems.push(basisSource);
    }

    if (sourceSystems.length === 1 && sourceSystems[0] === 'HEALTHROSTER') {
      return { source_key: 'HEALTHROSTER_WEEKLY', source_system: 'HEALTHROSTER', source_systems: sourceSystems, is_mixed: false };
    }

    if (sourceSystems.length === 1 && sourceSystems[0] === 'NHSP') {
      return { source_key: 'NHSP_WEEKLY', source_system: 'NHSP', source_systems: sourceSystems, is_mixed: false };
    }

    if (sourceSystems.length > 1) {
      return { source_key: 'IMPORTED_WEEKLY_MIXED', source_system: 'IMPORTED_MIXED', source_systems: sourceSystems, is_mixed: true };
    }

    return { source_key: 'IMPORTED_WEEKLY', source_system: null, source_systems: [], is_mixed: false };
  };

  const evidenceSource = resolveImportedWeeklyEvidenceSource(shiftsArr, basis);
  const allowEmptyShiftsWrite = (lockedSegsAll.length > 0) || (staleReason === 'IMPORT_CANCEL_DETACH');

  if (!shiftsArr.length && !allowEmptyShiftsWrite) return { ok: false, reason: 'NO_SHIFTS' };

  // ✅ Policy snapshot: prefer override; else old behaviour (fetch by week-ending/first date)
  let policy_snapshot_json = {};
  if (hasPolicyOverride) {
    policy_snapshot_json = policy_override;
  } else {
    try {
      const we = (ts && ts.week_ending_date)
        ? String(ts.week_ending_date)
        : (shiftsArr?.[0]?.work_date ? String(shiftsArr[0].work_date) : null);
      policy_snapshot_json = (we && client_id) ? (await getPolicyCached(client_id, we, {
        contract_id: contract?.id || null, timesheet_id: ts?.timesheet_id || null, workflow: 'IMPORT'
      })) : {};
      if (!policy_snapshot_json || typeof policy_snapshot_json !== 'object') policy_snapshot_json = {};
    } catch {
      policy_snapshot_json = {};
    }
  }

  // Cache policies by date (only used when no policy_override)
  const policyByDate = new Map();

  const lockedSegmentsOut = [];
  const unlockedSegmentsOut = [];
  const usedLocked = new Set();

  // Build segments: locked evidence unchanged + unlocked recomputed from current truth (shifts)
  for (const sh of shiftsArr) {
    const workDate = sh && sh.work_date;
    if (!workDate || !sh.start_utc || !sh.end_utc) continue;

    const stableKey = _stableKeyFromShift(sh);
    const computed_segment_id = _stableSegId(ts.timesheet_id, stableKey);
    const legacy_segment_id = (sh && sh.id != null) ? `nhsp:${sh.id}` : null;
    const nhsp_shift_id = (sh && sh.id != null) ? String(sh.id) : null;
    const external_row_key = (sh && sh.external_row_key != null) ? String(sh.external_row_key) : null;

    // If this shift corresponds to a LOCKED segment in existing evidence, carry it forward unchanged
    let lockedMatch = null;
    if (nhsp_shift_id) lockedMatch = lockedSegByNhspShiftId.get(String(nhsp_shift_id).trim()) || null;
    if (!lockedMatch && external_row_key) lockedMatch = lockedSegByExternalRowKey.get(String(external_row_key).trim()) || null;
    if (!lockedMatch && stableKey) lockedMatch = lockedSegByKey.get(stableKey) || null;
    if (!lockedMatch && legacy_segment_id) lockedMatch = lockedSegByLegacyId.get(legacy_segment_id) || null;
    if (!lockedMatch) lockedMatch = lockedSegByLegacyId.get(computed_segment_id) || null;

    if (lockedMatch) {
      const uk = _segUniqKey(lockedMatch);
      if (!usedLocked.has(uk)) {
        usedLocked.add(uk);
        lockedSegmentsOut.push(lockedMatch);
      }
      continue;
    }

    // Unlocked: recompute from truth
    let policy = null;
    if (hasPolicyOverride) {
      policy = policy_override;
    } else {
      policy = policyByDate.get(workDate);
      if (!policy) {
        policy = await getPolicyCached(client_id, workDate, {
          contract_id: contract?.id || null, timesheet_id: ts?.timesheet_id || null, workflow: 'IMPORT'
        });
        policyByDate.set(workDate, policy);
      }
    }

    let segs = [[sh.start_utc, sh.end_utc]];
    segs = subtractBreak(segs, null, null, sh.break_mins || 0);

    const hours = classifyMinutes(env, policy, segs);

    const payEx = round2(
      (hours.hours_day   || 0) * asNumberLocal(pay.day)   +
      (hours.hours_night || 0) * asNumberLocal(pay.night) +
      (hours.hours_sat   || 0) * asNumberLocal(pay.sat)   +
      (hours.hours_sun   || 0) * asNumberLocal(pay.sun)   +
      (hours.hours_bh    || 0) * asNumberLocal(pay.bh)
    );

    const chgEx = round2(
      (hours.hours_day   || 0) * asNumberLocal(chg.day)   +
      (hours.hours_night || 0) * asNumberLocal(chg.night) +
      (hours.hours_sat   || 0) * asNumberLocal(chg.sat)   +
      (hours.hours_sun   || 0) * asNumberLocal(chg.sun)   +
      (hours.hours_bh    || 0) * asNumberLocal(chg.bh)
    );

    const preserved =
      (nhsp_shift_id && preservedByNhspShiftId.get(String(nhsp_shift_id))) ||
      (external_row_key && preservedByExternalRowKey.get(String(external_row_key))) ||
      (stableKey && preservedByKey.get(stableKey)) ||
      (legacy_segment_id && preservedByLegacyId.get(legacy_segment_id)) ||
      preservedByLegacyId.get(computed_segment_id) ||
      null;

    const exclude_from_pay =
      (preserved && typeof preserved.exclude_from_pay === 'boolean') ? preserved.exclude_from_pay : false;

    const invoice_target_week_start =
      (preserved && preserved.invoice_target_week_start != null) ? preserved.invoice_target_week_start : undefined;

    // ✅ Base ref: NHSP-provided reference (or existing shift ref) — never from schedule.
    const baseRef =
      _normStr(sh.nhsp_ref_num || sh.ref_num || '') || null;

    // ✅ If validated OK for HR weekly, override with imported HealthRoster Request Id when matched.
    let segRefNum = baseRef;

    if (useImportRefs) {
      const dateYmd = String(workDate).slice(0, 10);
      const sMs = parseUtcMs(sh?.start_utc);
      const eMs = parseUtcMs(sh?.end_utc);

      let hrRef = null;

      if (dateYmd && sMs != null && eMs != null) {
        const k2 = `${dateYmd}|${sMs}|${eMs}`;
        hrRef = hrRefByKey.get(k2) || null;
      }

      // Fallback: if exactly one HR shift exists for that date, use its ref_num
      if (!hrRef && dateYmd && hrListByDate.has(dateYmd)) {
        const arr = hrListByDate.get(dateYmd) || [];
        const uniq = new Set(arr.map(x => String(x.ref_num || '').trim()).filter(Boolean));
        if (uniq.size === 1) {
          hrRef = Array.from(uniq)[0];
        }
      }

      // After validation, use import ref only; if no match, leave null (do not inject non-import refs).
      segRefNum = hrRef ? String(hrRef) : null;
    }

    unlockedSegmentsOut.push({
      segment_id: computed_segment_id,

      // embed stable source identity into segment JSON
      nhsp_shift_id: nhsp_shift_id || null,
      shift_id: nhsp_shift_id || null,
      external_row_key: external_row_key || null,

      date: workDate,
      ward: sh.ward || null,
      start_utc: sh.start_utc,
      end_utc: sh.end_utc,
      break_mins: sh.break_mins || 0,

      hours_day:   hours.hours_day   || 0,
      hours_night: hours.hours_night || 0,
      hours_sat:   hours.hours_sat   || 0,
      hours_sun:   hours.hours_sun   || 0,
      hours_bh:    hours.hours_bh    || 0,

      pay_amount:    payEx,
      charge_amount: chgEx,

      exclude_from_pay,
      ...(invoice_target_week_start != null ? { invoice_target_week_start } : {}),

      // ✅ ref_num: canonical for invoice + PDF + QR
      ref_num: segRefNum,

      // request_id kept as source metadata only
      hr_request_id: (sh.hr_request_id || null) || null,
      request_id: (sh.hr_request_id || sh.request_id || null) || null,
      latest_import_id: (sh.latest_import_id || nhspImportId || null) || null,

      held_back_reason: sh.held_back_reason || null,
      source_system: normaliseImportedSourceSystem(sh.source_system || basis) || evidenceSource.source_system || null
    });
  }

  // Append any LOCKED segments that are not present in current truth (detached/missing)
  for (const sLocked of lockedSegsAll) {
    const uk = _segUniqKey(sLocked);
    if (!usedLocked.has(uk)) {
      usedLocked.add(uk);
      lockedSegmentsOut.push(sLocked);
    }
  }

  // Final merged evidence: locked (unchanged) + unlocked (recomputed)
  const segments = lockedSegmentsOut.concat(unlockedSegmentsOut);

  // Recompute totals purely from final segments (locked amounts are taken from locked JSON unchanged)
  let sumDay = 0, sumNight = 0, sumSat = 0, sumSun = 0, sumBh = 0;
  let totalPayEx = 0, totalChgEx = 0;

  for (const s of segments) {
    sumDay   += asNumberLocal(s && s.hours_day);
    sumNight += asNumberLocal(s && s.hours_night);
    sumSat   += asNumberLocal(s && s.hours_sat);
    sumSun   += asNumberLocal(s && s.hours_sun);
    sumBh    += asNumberLocal(s && s.hours_bh);

    totalPayEx += asNumberLocal(s && s.pay_amount);
    totalChgEx += asNumberLocal(s && s.charge_amount);
  }

  totalPayEx = round2(totalPayEx);
  totalChgEx = round2(totalChgEx);

  // ✅ ERNI-aware margin (policy comes from SQL context via policy_override / policy_snapshot_json)
  const _polForMargin = (hasPolicyOverride ? policy_override : policy_snapshot_json) || {};
  const _applyErniTo  = String(_polForMargin?.apply_erni_to || 'PAYE_ONLY').toUpperCase();
  const _erniPctRaw   = Number(_polForMargin?.erni_pct ?? 0);

  let _erniMult = 1;
  if (Number.isFinite(_erniPctRaw) && _erniPctRaw > 0) {
    const p = _erniPctRaw > 1 ? (_erniPctRaw / 100) : _erniPctRaw;
    _erniMult = 1 + p;
  }

  const _payMethodU = String(method || '').toUpperCase();
  const _erniApplies =
    (_applyErniTo === 'ALL') ||
    (_applyErniTo === 'PAYE_ONLY' && _payMethodU === 'PAYE');

  const _payCostEx = round2(_erniApplies ? (totalPayEx * _erniMult) : totalPayEx);
  const marginEx = round2(totalChgEx - _payCostEx);

  const invoice_breakdown_json = {
    mode: 'SEGMENTS',
    segments,
    totals: { total_pay_ex_vat: totalPayEx, total_charge_ex_vat: totalChgEx, margin_ex_vat: marginEx }
  };

  const hours_day   = round2(sumDay);
  const hours_night = round2(sumNight);
  const hours_sat   = round2(sumSat);
  const hours_sun   = round2(sumSun);
  const hours_bh    = round2(sumBh);
  const total_hours = round2(hours_day + hours_night + hours_sat + hours_sun + hours_bh);

  const pay_wtr_rate_pct_snapshot =
    (String(method || '').toUpperCase() === 'PAYE')
      ? (Number.isFinite(Number(policy_snapshot_json?.holiday_pay_pct)) ? Number(policy_snapshot_json.holiday_pay_pct) : null)
      : null;

  // Policy B gating: bases require authorisation before “ready”
  const basisU = String(basis || '').toUpperCase();
  const isAuthoriseGatedBase =
    (basisU === 'NHSP' ||
     basisU === 'NHSP_ADJUSTMENT' ||
     basisU === 'HEALTHROSTER_SELF_BILL' ||
     basisU === 'HEALTHROSTER_ADJUSTMENT');

  const isAuthorised = !!(ts && ts.authorised_at_server);
  const processing_status = (isAuthoriseGatedBase && !isAuthorised) ? 'PENDING_AUTH' : 'READY_FOR_INVOICE';

  const snapshot = {
    timesheet_id: ts.timesheet_id,
    timesheet_version: ts.version || 1,

    basis,
    nhsp_import_id: nhspImportId || null,

    occupant_key_norm: ts.occupant_key_norm || null,

    candidate_id,
    client_id,
    role: contract.role || null,
    band: contract.band || null,

    pay_method: method,

    policy_snapshot_json,
    rate_source_refs_json: { mode: 'CONTRACT_RATES_JSON', contract_id: contract.id || null },

    hours_day,
    hours_night,
    hours_sat,
    hours_sun,
    hours_bh,

    pay_day:    pay.day   ?? null,
    pay_night:  pay.night ?? null,
    pay_sat:    pay.sat   ?? null,
    pay_sun:    pay.sun   ?? null,
    pay_bh:     pay.bh    ?? null,

    charge_day:   chg.day   ?? null,
    charge_night: chg.night ?? null,
    charge_sat:   chg.sat   ?? null,
    charge_sun:   chg.sun   ?? null,
    charge_bh:    chg.bh    ?? null,

    additional_units_json: {},
    additional_pay_ex_vat: 0,
    additional_charge_ex_vat: 0,
    additional_margin_ex_vat: 0,

    total_hours,
    total_pay_ex_vat: totalPayEx,
    total_charge_ex_vat: totalChgEx,
    margin_ex_vat: marginEx, // ERNI-aware for PAYE

    pay_wtr_rate_pct_snapshot,

    candidate_assignment: candidate_id ? 'ASSIGNED' : 'UNASSIGNED',
    processing_status,

    has_rate_issue: false,
    has_pay_channel_issue: false,

    invoice_breakdown_json,

    external_source_rows_json: {
      [evidenceSource.source_key]: shiftsArr.map(sh => (sh ? ({
        date: sh.work_date,
        source_system: normaliseImportedSourceSystem(sh.source_system || evidenceSource.source_system) || evidenceSource.source_system || null,
        reference:
          (sh.nhsp_ref_num || sh.ref_num || (sh.payload_json && (sh.payload_json.ref_num || sh.payload_json.Reference))) || null,
        nhsp_shift_id: sh.id,
        shift_id: sh.id,
        external_row_key: sh.external_row_key || null,
        request_id: (sh.hr_request_id || sh.request_id || null) || null,
        hr_request_id: (sh.hr_request_id || null) || null,
        latest_import_id: (sh.latest_import_id || nhspImportId || null) || null,
        raw_row: sh.payload_json || null
      }) : null)).filter(Boolean),
      source_system: evidenceSource.source_system || null,
      source_systems: evidenceSource.source_systems || [],
      evidence_kind: evidenceSource.source_key
    }
  };

  // Optional: apply HR cross-check enrichment BEFORE write (mutates snapshot)
  if (typeof enrichTsfinWithHrCrosscheck === 'function') {
    try {
      await enrichTsfinWithHrCrosscheck(env, ts, snapshot, hr_eff_flags || null, hr_preloaded_shifts || null);
    } catch {}
  }

  // Optional: write through SQL batch writer (single-row)
  if (write_now) {
    if (!outbox_id) throw new Error('buildNhspWeeklySnapshot: write_now requires options.outbox_id');
    const wr = await rpcTsfinWriteSnapshotsAndComplete(env, {
      rows: [{ outbox_id, timesheet_id: ts.timesheet_id, snapshot }]
    });
    return { ok: true, snapshot, write: wr };
  }

  return { ok: true, snapshot };
}


// Self-bill helper: reuse existing invoice for (client, week) if possible,
// otherwise create a new self-bill invoice header.

hunks.after:
async function buildNhspWeeklySnapshot(
  env,
  ts,
  contract,
  shifts,
  nhspImportId,
  basis = 'NHSP',
  getPolicyCached,
  curFin,
  options = {}
) {
  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const asNumberLocal = (v) => (v == null ? 0 : Number(v) || 0);

  const {
    outbox_id = null,
    write_now = false,
    // optional HR enrich inputs (so snapshot contains hr_crosscheck_* before write)
    hr_eff_flags = null,
    hr_preloaded_shifts = null,

    // ✅ allow caller to pass SQL policy (ctx.out_policy) to avoid REST
    policy_override = null,

    // ✅ NEW: validation state (so ref_num can be overridden ONLY after validation OK)
    hr_validation_status = null,
    hr_validation_reason_code = null,
    hr_validation_source_kind = null
  } = (options && typeof options === 'object') ? options : {};

  const hasPolicyOverride = !!(policy_override && typeof policy_override === 'object');

  const pc  = payChargeFromContract(contract);
  const pay = pc?.pay || null;
  const chg = pc?.charge || null;
  const method = pc?.method || contract?.pay_method_snapshot || contract?.pay_method || null;

  if (!pay || !chg) return { ok: false, reason: 'CONTRACT_RATES_MISSING' };

  const candidate_id = contract.candidate_id || null;
  const client_id    = contract.client_id   || null;

  // ---- Policy helper ----
  // If policy_override is provided, we do not need getPolicyCached at all.
  if (!hasPolicyOverride && typeof getPolicyCached !== 'function') {
    throw new Error('buildNhspWeeklySnapshot: getPolicyCached must be provided (or pass options.policy_override)');
  }

  // ─────────────────────────────────────────────────────────────
  // ✅ Stable segment identity helpers (NHSP weekly)
  //
  // Fixes delayed segment corruption by:
  // - generating deterministic segment_id from immutable shift attributes (not sh.id)
  // - preserving per-segment controls by mapping old→new using the same fingerprint
  //
  // NOTE: We intentionally do NOT include ref_num in identity (it may be amended later).
  // ─────────────────────────────────────────────────────────────
  const _normStr = (v) => (v == null ? '' : String(v).trim());
  const _normNumInt = (v, d = 0) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };

  // FNV-1a 32-bit hash (deterministic, fast, no async crypto)
  const _hash32 = (s) => {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193);
    }
    return (h >>> 0).toString(16).padStart(8, '0');
  };

  const _stableKeyFromParts = (dateYmd, startUtc, endUtc, breakMins, requestId) => {
    const d = _normStr(dateYmd);
    const s = _normStr(startUtc);
    const e = _normStr(endUtc);
    const b = _normNumInt(breakMins ?? 0, 0);
    const r = _normStr(requestId); // optional but stable if present; safe to include
    // If we have no useful timestamps, return empty => will fall back to legacy segment_id matching only.
    if (!d && !s && !e) return '';
    return `d:${d}|s:${s}|e:${e}|b:${b}|r:${r}`;
  };

  const _stableKeyFromShift = (sh) => {
    if (!sh || typeof sh !== 'object') return '';
    const workDate = _normStr(sh.work_date);
    const startUtc = _normStr(sh.start_utc);
    const endUtc   = _normStr(sh.end_utc);
    const breakM   = _normNumInt(sh.break_mins ?? sh.break_minutes ?? 0, 0);
    const reqId    = _normStr(sh.hr_request_id || sh.request_id || '');
    return _stableKeyFromParts(workDate, startUtc, endUtc, breakM, reqId);
  };

  const _stableKeyFromExistingSegment = (s) => {
    if (!s || typeof s !== 'object') return '';
    const dateYmd = _normStr(s.date);
    const startUtc = _normStr(s.start_utc || s.start_iso || '');
    const endUtc   = _normStr(s.end_utc || s.end_iso || '');
    const breakM   = _normNumInt(s.break_mins ?? s.break_minutes ?? 0, 0);
    const reqId    = _normStr(s.request_id || '');
    return _stableKeyFromParts(dateYmd, startUtc, endUtc, breakM, reqId);
  };

  const _stableSegId = (tsId, stableKey) => {
    const k = _normStr(stableKey);
    if (!k) return `nhsp:${tsId}:unknown`;
    return `nhsp:${tsId}:${_hash32(k)}`;
  };

  // ─────────────────────────────────────────────────────────────
  // ✅ HR import ref override (only after validation OK/OVERRIDDEN)
  // Applies when HR validation is required and the validation context is weekly HR.
  // ─────────────────────────────────────────────────────────────
  const boolishLocal = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on' || s === 't');
  };

  const hrValidationRequired =
    boolishLocal(hr_eff_flags?.client_hr_validation_required) ||
    boolishLocal(hr_eff_flags?.hr_validation_required_for_invoice) ||
    false;

  const valStatusU = String(hr_validation_status || '').trim().toUpperCase();
  const valReasonU = String(hr_validation_reason_code || '').trim().toUpperCase();

  const isValidatedOk = hr_validation_source_kind === 'AGENCY_INVOICE_WEEK'
    ? valStatusU === 'VALIDATION_OK'
    : (valStatusU === 'VALIDATION_OK' || valStatusU === 'OVERRIDDEN' || valStatusU === 'OVERRIDE');

  const isWeeklyHrValidation = hr_validation_source_kind === 'AGENCY_INVOICE_WEEK'
    || ((!valReasonU) ? true : valReasonU.includes('HEALTHROSTER_WEEKLY'));

  const useImportRefs = !!(hrValidationRequired && isValidatedOk && isWeeklyHrValidation);

  const parseUtcMs = (v) => {
    if (v == null) return null;
    let s = String(v).trim();
    if (!s) return null;
    // tolerate "YYYY-MM-DD HH:MM:SS+00"
    if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}/.test(s) && !s.includes('T')) {
      s = s.replace(' ', 'T');
    }
    const d = new Date(s);
    if (Number.isNaN(d.getTime())) return null;
    return d.getTime();
  };

  // `${date}|${startMs}|${endMs}` -> ref_num
  const hrRefByKey = new Map();
  const hrListByDate = new Map();
  if (useImportRefs && Array.isArray(hr_preloaded_shifts) && hr_preloaded_shifts.length) {
    for (const sh of hr_preloaded_shifts) {
      const ss = String(sh?.source_system || '').trim().toUpperCase();
      if (ss !== 'HEALTHROSTER') continue;

      const d = sh?.work_date ? String(sh.work_date).slice(0, 10) : '';
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;

      const ref = (sh?.ref_num != null) ? String(sh.ref_num).trim() : '';
      if (!ref) continue;

      const sMs = parseUtcMs(sh?.start_utc);
      const eMs = parseUtcMs(sh?.end_utc);
      if (sMs == null || eMs == null) continue;

      const k = `${d}|${sMs}|${eMs}`;
      if (!hrRefByKey.has(k)) hrRefByKey.set(k, ref);

      if (!hrListByDate.has(d)) hrListByDate.set(d, []);
      hrListByDate.get(d).push({ startMs: sMs, endMs: eMs, ref_num: ref });
    }
  }

  // ─────────────────────────────────────────────────────────────
  // Preserve existing TSFIN evidence:
  // - meta controls for unlocked recompute (exclude_from_pay, invoice_target_week_start)
  // - FULL locked segment objects (invoice_locked_invoice_id != null/empty) to preserve evidence exactly
  // ─────────────────────────────────────────────────────────────
  const preservedByKey = new Map();
  const preservedByLegacyId = new Map();
  const preservedByNhspShiftId = new Map();
  const preservedByExternalRowKey = new Map();

  const lockedSegByKey = new Map();
  const lockedSegByLegacyId = new Map();
  const lockedSegByNhspShiftId = new Map();
  const lockedSegByExternalRowKey = new Map();
  const lockedSegsAll = [];

  function btrim(s) { return String(s).trim(); }
  function nullif(a, b) { return (a === b) ? null : a; }

  const _segUniqKey = (s) => {
    const sid = (s && s.segment_id != null) ? String(s.segment_id).trim() : '';
    if (sid) return `sid:${sid}`;
    const nid = (s && s.nhsp_shift_id != null) ? String(s.nhsp_shift_id).trim() : '';
    if (nid) return `nhsp:${nid}`;
    const ek  = (s && s.external_row_key != null) ? String(s.external_row_key).trim() : '';
    if (ek) return `ext:${ek}`;
    const sk  = _stableKeyFromExistingSegment(s);
    if (sk) return `stk:${sk}`;
    return `obj:${btrim(JSON.stringify(s || {})).slice(0, 200)}`;
  };

  try {
    const ib = curFin?.invoice_breakdown_json || null;
    const mode = String(ib?.mode || '').toUpperCase();
    const segs = Array.isArray(ib?.segments) ? ib.segments : null;

    if (mode === 'SEGMENTS' && segs) {
      for (const s of segs) {
        const segment_id = (s && s.segment_id != null) ? String(s.segment_id) : null;

        const invLockRaw = (s && s.invoice_locked_invoice_id != null) ? String(s.invoice_locked_invoice_id) : '';
        const invLockTrim = btrim(invLockRaw);
        const isLocked = invLockTrim !== '';

        const meta = {
          exclude_from_pay:
            (typeof s.exclude_from_pay === 'boolean') ? s.exclude_from_pay : undefined,
          invoice_target_week_start:
            (s.invoice_target_week_start != null) ? String(s.invoice_target_week_start) : undefined,
          invoice_locked_invoice_id:
            (invLockTrim !== '') ? invLockTrim : undefined
        };

        if (segment_id) preservedByLegacyId.set(segment_id, meta);

        const key = _stableKeyFromExistingSegment(s);
        if (key) preservedByKey.set(key, meta);

        const nhspShiftId = (s && s.nhsp_shift_id != null) ? String(s.nhsp_shift_id).trim() : '';
        const extKey = (s && s.external_row_key != null) ? String(s.external_row_key).trim() : '';
        if (nhspShiftId) preservedByNhspShiftId.set(nhspShiftId, meta);
        if (extKey) preservedByExternalRowKey.set(extKey, meta);

        if (isLocked) {
          lockedSegsAll.push(s);
          if (segment_id) lockedSegByLegacyId.set(segment_id, s);
          if (key) lockedSegByKey.set(key, s);
          if (nhspShiftId) lockedSegByNhspShiftId.set(nhspShiftId, s);
          if (extKey) lockedSegByExternalRowKey.set(extKey, s);
        }
      }
    }
  } catch {}

  const staleReason = (curFin && curFin.stale_reason != null) ? String(curFin.stale_reason) : '';

  const shiftsArr = Array.isArray(shifts) ? shifts : [];

  const normaliseImportedSourceSystem = (value) => {
    const raw = String(value || '').trim().toUpperCase();
    if (!raw) return null;
    if (raw === 'HEALTHROSTER' || raw === 'HR' || raw === 'HEALTH_ROSTER') return 'HEALTHROSTER';
    if (raw === 'NHSP') return 'NHSP';
    return raw;
  };

  const resolveImportedWeeklyEvidenceSource = (sourceShifts, basisForEvidence) => {
    const sourceSystems = [];
    for (const sh of Array.isArray(sourceShifts) ? sourceShifts : []) {
      const source = normaliseImportedSourceSystem(sh?.source_system);
      if (source && !sourceSystems.includes(source)) sourceSystems.push(source);
    }

    if (!sourceSystems.length) {
      const basisSource = normaliseImportedSourceSystem(basisForEvidence);
      if (basisSource) sourceSystems.push(basisSource);
    }

    if (sourceSystems.length === 1 && sourceSystems[0] === 'HEALTHROSTER') {
      return { source_key: 'HEALTHROSTER_WEEKLY', source_system: 'HEALTHROSTER', source_systems: sourceSystems, is_mixed: false };
    }

    if (sourceSystems.length === 1 && sourceSystems[0] === 'NHSP') {
      return { source_key: 'NHSP_WEEKLY', source_system: 'NHSP', source_systems: sourceSystems, is_mixed: false };
    }

    if (sourceSystems.length > 1) {
      return { source_key: 'IMPORTED_WEEKLY_MIXED', source_system: 'IMPORTED_MIXED', source_systems: sourceSystems, is_mixed: true };
    }

    return { source_key: 'IMPORTED_WEEKLY', source_system: null, source_systems: [], is_mixed: false };
  };

  const evidenceSource = resolveImportedWeeklyEvidenceSource(shiftsArr, basis);
  const allowEmptyShiftsWrite = (lockedSegsAll.length > 0) || (staleReason === 'IMPORT_CANCEL_DETACH');

  if (!shiftsArr.length && !allowEmptyShiftsWrite) return { ok: false, reason: 'NO_SHIFTS' };

  // ✅ Policy snapshot: prefer override; else old behaviour (fetch by week-ending/first date)
  let policy_snapshot_json = {};
  if (hasPolicyOverride) {
    policy_snapshot_json = policy_override;
  } else {
    try {
      const we = (ts && ts.week_ending_date)
        ? String(ts.week_ending_date)
        : (shiftsArr?.[0]?.work_date ? String(shiftsArr[0].work_date) : null);
      policy_snapshot_json = (we && client_id) ? (await getPolicyCached(client_id, we, {
        contract_id: contract?.id || null, timesheet_id: ts?.timesheet_id || null, workflow: 'IMPORT'
      })) : {};
      if (!policy_snapshot_json || typeof policy_snapshot_json !== 'object') policy_snapshot_json = {};
    } catch {
      policy_snapshot_json = {};
    }
  }

  // Cache policies by date (only used when no policy_override)
  const policyByDate = new Map();

  const lockedSegmentsOut = [];
  const unlockedSegmentsOut = [];
  const usedLocked = new Set();

  // Build segments: locked evidence unchanged + unlocked recomputed from current truth (shifts)
  for (const sh of shiftsArr) {
    const workDate = sh && sh.work_date;
    if (!workDate || !sh.start_utc || !sh.end_utc) continue;

    const stableKey = _stableKeyFromShift(sh);
    const computed_segment_id = _stableSegId(ts.timesheet_id, stableKey);
    const legacy_segment_id = (sh && sh.id != null) ? `nhsp:${sh.id}` : null;
    const nhsp_shift_id = (sh && sh.id != null) ? String(sh.id) : null;
    const external_row_key = (sh && sh.external_row_key != null) ? String(sh.external_row_key) : null;

    // If this shift corresponds to a LOCKED segment in existing evidence, carry it forward unchanged
    let lockedMatch = null;
    if (nhsp_shift_id) lockedMatch = lockedSegByNhspShiftId.get(String(nhsp_shift_id).trim()) || null;
    if (!lockedMatch && external_row_key) lockedMatch = lockedSegByExternalRowKey.get(String(external_row_key).trim()) || null;
    if (!lockedMatch && stableKey) lockedMatch = lockedSegByKey.get(stableKey) || null;
    if (!lockedMatch && legacy_segment_id) lockedMatch = lockedSegByLegacyId.get(legacy_segment_id) || null;
    if (!lockedMatch) lockedMatch = lockedSegByLegacyId.get(computed_segment_id) || null;

    if (lockedMatch) {
      const uk = _segUniqKey(lockedMatch);
      if (!usedLocked.has(uk)) {
        usedLocked.add(uk);
        lockedSegmentsOut.push(lockedMatch);
      }
      continue;
    }

    // Unlocked: recompute from truth
    let policy = null;
    if (hasPolicyOverride) {
      policy = policy_override;
    } else {
      policy = policyByDate.get(workDate);
      if (!policy) {
        policy = await getPolicyCached(client_id, workDate, {
          contract_id: contract?.id || null, timesheet_id: ts?.timesheet_id || null, workflow: 'IMPORT'
        });
        policyByDate.set(workDate, policy);
      }
    }

    let segs = [[sh.start_utc, sh.end_utc]];
    segs = subtractBreak(segs, null, null, sh.break_mins || 0);

    const hours = classifyMinutes(env, policy, segs);

    const payEx = round2(
      (hours.hours_day   || 0) * asNumberLocal(pay.day)   +
      (hours.hours_night || 0) * asNumberLocal(pay.night) +
      (hours.hours_sat   || 0) * asNumberLocal(pay.sat)   +
      (hours.hours_sun   || 0) * asNumberLocal(pay.sun)   +
      (hours.hours_bh    || 0) * asNumberLocal(pay.bh)
    );

    const chgEx = round2(
      (hours.hours_day   || 0) * asNumberLocal(chg.day)   +
      (hours.hours_night || 0) * asNumberLocal(chg.night) +
      (hours.hours_sat   || 0) * asNumberLocal(chg.sat)   +
      (hours.hours_sun   || 0) * asNumberLocal(chg.sun)   +
      (hours.hours_bh    || 0) * asNumberLocal(chg.bh)
    );

    const preserved =
      (nhsp_shift_id && preservedByNhspShiftId.get(String(nhsp_shift_id))) ||
      (external_row_key && preservedByExternalRowKey.get(String(external_row_key))) ||
      (stableKey && preservedByKey.get(stableKey)) ||
      (legacy_segment_id && preservedByLegacyId.get(legacy_segment_id)) ||
      preservedByLegacyId.get(computed_segment_id) ||
      null;

    const exclude_from_pay =
      (preserved && typeof preserved.exclude_from_pay === 'boolean') ? preserved.exclude_from_pay : false;

    const invoice_target_week_start =
      (preserved && preserved.invoice_target_week_start != null) ? preserved.invoice_target_week_start : undefined;

    // ✅ Base ref: NHSP-provided reference (or existing shift ref) — never from schedule.
    const baseRef =
      _normStr(sh.nhsp_ref_num || sh.ref_num || '') || null;

    // ✅ If validated OK for HR weekly, override with imported HealthRoster Request Id when matched.
    let segRefNum = baseRef;

    if (useImportRefs) {
      const dateYmd = String(workDate).slice(0, 10);
      const sMs = parseUtcMs(sh?.start_utc);
      const eMs = parseUtcMs(sh?.end_utc);

      let hrRef = null;

      if (dateYmd && sMs != null && eMs != null) {
        const k2 = `${dateYmd}|${sMs}|${eMs}`;
        hrRef = hrRefByKey.get(k2) || null;
      }

      // Fallback: if exactly one HR shift exists for that date, use its ref_num
      if (!hrRef && dateYmd && hrListByDate.has(dateYmd)) {
        const arr = hrListByDate.get(dateYmd) || [];
        const uniq = new Set(arr.map(x => String(x.ref_num || '').trim()).filter(Boolean));
        if (uniq.size === 1) {
          hrRef = Array.from(uniq)[0];
        }
      }

      // After validation, use import ref only; if no match, leave null (do not inject non-import refs).
      segRefNum = hrRef ? String(hrRef) : null;
    }

    unlockedSegmentsOut.push({
      segment_id: computed_segment_id,

      // embed stable source identity into segment JSON
      nhsp_shift_id: nhsp_shift_id || null,
      shift_id: nhsp_shift_id || null,
      external_row_key: external_row_key || null,

      date: workDate,
      ward: sh.ward || null,
      start_utc: sh.start_utc,
      end_utc: sh.end_utc,
      break_mins: sh.break_mins || 0,

      hours_day:   hours.hours_day   || 0,
      hours_night: hours.hours_night || 0,
      hours_sat:   hours.hours_sat   || 0,
      hours_sun:   hours.hours_sun   || 0,
      hours_bh:    hours.hours_bh    || 0,

      pay_amount:    payEx,
      charge_amount: chgEx,

      exclude_from_pay,
      ...(invoice_target_week_start != null ? { invoice_target_week_start } : {}),

      // ✅ ref_num: canonical for invoice + PDF + QR
      ref_num: segRefNum,

      // request_id kept as source metadata only
      hr_request_id: (sh.hr_request_id || null) || null,
      request_id: (sh.hr_request_id || sh.request_id || null) || null,
      latest_import_id: (sh.latest_import_id || nhspImportId || null) || null,

      held_back_reason: sh.held_back_reason || null,
      source_system: normaliseImportedSourceSystem(sh.source_system || basis) || evidenceSource.source_system || null
    });
  }

  // Append any LOCKED segments that are not present in current truth (detached/missing)
  for (const sLocked of lockedSegsAll) {
    const uk = _segUniqKey(sLocked);
    if (!usedLocked.has(uk)) {
      usedLocked.add(uk);
      lockedSegmentsOut.push(sLocked);
    }
  }

  // Final merged evidence: locked (unchanged) + unlocked (recomputed)
  const segments = lockedSegmentsOut.concat(unlockedSegmentsOut);

  // Recompute totals purely from final segments (locked amounts are taken from locked JSON unchanged)
  let sumDay = 0, sumNight = 0, sumSat = 0, sumSun = 0, sumBh = 0;
  let totalPayEx = 0, totalChgEx = 0;

  for (const s of segments) {
    sumDay   += asNumberLocal(s && s.hours_day);
    sumNight += asNumberLocal(s && s.hours_night);
    sumSat   += asNumberLocal(s && s.hours_sat);
    sumSun   += asNumberLocal(s && s.hours_sun);
    sumBh    += asNumberLocal(s && s.hours_bh);

    totalPayEx += asNumberLocal(s && s.pay_amount);
    totalChgEx += asNumberLocal(s && s.charge_amount);
  }

  totalPayEx = round2(totalPayEx);
  totalChgEx = round2(totalChgEx);

  // ✅ ERNI-aware margin (policy comes from SQL context via policy_override / policy_snapshot_json)
  const _polForMargin = (hasPolicyOverride ? policy_override : policy_snapshot_json) || {};
  const _applyErniTo  = String(_polForMargin?.apply_erni_to || 'PAYE_ONLY').toUpperCase();
  const _erniPctRaw   = Number(_polForMargin?.erni_pct ?? 0);

  let _erniMult = 1;
  if (Number.isFinite(_erniPctRaw) && _erniPctRaw > 0) {
    const p = _erniPctRaw > 1 ? (_erniPctRaw / 100) : _erniPctRaw;
    _erniMult = 1 + p;
  }

  const _payMethodU = String(method || '').toUpperCase();
  const _erniApplies =
    (_applyErniTo === 'ALL') ||
    (_applyErniTo === 'PAYE_ONLY' && _payMethodU === 'PAYE');

  const _payCostEx = round2(_erniApplies ? (totalPayEx * _erniMult) : totalPayEx);
  const marginEx = round2(totalChgEx - _payCostEx);

  const invoice_breakdown_json = {
    mode: 'SEGMENTS',
    segments,
    totals: { total_pay_ex_vat: totalPayEx, total_charge_ex_vat: totalChgEx, margin_ex_vat: marginEx }
  };

  const hours_day   = round2(sumDay);
  const hours_night = round2(sumNight);
  const hours_sat   = round2(sumSat);
  const hours_sun   = round2(sumSun);
  const hours_bh    = round2(sumBh);
  const total_hours = round2(hours_day + hours_night + hours_sat + hours_sun + hours_bh);

  const pay_wtr_rate_pct_snapshot =
    (String(method || '').toUpperCase() === 'PAYE')
      ? (Number.isFinite(Number(policy_snapshot_json?.holiday_pay_pct)) ? Number(policy_snapshot_json.holiday_pay_pct) : null)
      : null;

  // Policy B gating: bases require authorisation before “ready”
  const basisU = String(basis || '').toUpperCase();
  const isAuthoriseGatedBase =
    (basisU === 'NHSP' ||
     basisU === 'NHSP_ADJUSTMENT' ||
     basisU === 'HEALTHROSTER_SELF_BILL' ||
     basisU === 'HEALTHROSTER_ADJUSTMENT');

  const isAuthorised = !!(ts && ts.authorised_at_server);
  let processing_status = (isAuthoriseGatedBase && !isAuthorised) ? 'PENDING_AUTH' : 'READY_FOR_INVOICE';
  if (hr_validation_source_kind === 'AGENCY_INVOICE_WEEK' && hrValidationRequired) {
    processing_status = !isAuthorised ? 'PENDING_AUTH' : (!isValidatedOk ? 'READY_FOR_HR' : 'READY_FOR_INVOICE');
  }


  const snapshot = {
    timesheet_id: ts.timesheet_id,
    timesheet_version: ts.version || 1,

    basis,
    nhsp_import_id: nhspImportId || null,

    occupant_key_norm: ts.occupant_key_norm || null,

    candidate_id,
    client_id,
    role: contract.role || null,
    band: contract.band || null,

    pay_method: method,

    policy_snapshot_json,
    rate_source_refs_json: { mode: 'CONTRACT_RATES_JSON', contract_id: contract.id || null },

    hours_day,
    hours_night,
    hours_sat,
    hours_sun,
    hours_bh,

    pay_day:    pay.day   ?? null,
    pay_night:  pay.night ?? null,
    pay_sat:    pay.sat   ?? null,
    pay_sun:    pay.sun   ?? null,
    pay_bh:     pay.bh    ?? null,

    charge_day:   chg.day   ?? null,
    charge_night: chg.night ?? null,
    charge_sat:   chg.sat   ?? null,
    charge_sun:   chg.sun   ?? null,
    charge_bh:    chg.bh    ?? null,

    additional_units_json: {},
    additional_pay_ex_vat: 0,
    additional_charge_ex_vat: 0,
    additional_margin_ex_vat: 0,

    total_hours,
    total_pay_ex_vat: totalPayEx,
    total_charge_ex_vat: totalChgEx,
    margin_ex_vat: marginEx, // ERNI-aware for PAYE

    pay_wtr_rate_pct_snapshot,

    candidate_assignment: candidate_id ? 'ASSIGNED' : 'UNASSIGNED',
    processing_status,

    has_rate_issue: false,
    has_pay_channel_issue: false,

    invoice_breakdown_json,

    external_source_rows_json: {
      [evidenceSource.source_key]: shiftsArr.map(sh => (sh ? ({
        date: sh.work_date,
        source_system: normaliseImportedSourceSystem(sh.source_system || evidenceSource.source_system) || evidenceSource.source_system || null,
        reference:
          (sh.nhsp_ref_num || sh.ref_num || (sh.payload_json && (sh.payload_json.ref_num || sh.payload_json.Reference))) || null,
        nhsp_shift_id: sh.id,
        shift_id: sh.id,
        external_row_key: sh.external_row_key || null,
        request_id: (sh.hr_request_id || sh.request_id || null) || null,
        hr_request_id: (sh.hr_request_id || null) || null,
        latest_import_id: (sh.latest_import_id || nhspImportId || null) || null,
        raw_row: sh.payload_json || null
      }) : null)).filter(Boolean),
      source_system: evidenceSource.source_system || null,
      source_systems: evidenceSource.source_systems || [],
      evidence_kind: evidenceSource.source_key
    }
  };

  // Optional: apply HR cross-check enrichment BEFORE write (mutates snapshot)
  if (typeof enrichTsfinWithHrCrosscheck === 'function') {
    try {
      await enrichTsfinWithHrCrosscheck(env, ts, snapshot, hr_eff_flags || null, hr_preloaded_shifts || null);
    } catch {}
  }

  // Optional: write through SQL batch writer (single-row)
  if (write_now) {
    if (!outbox_id) throw new Error('buildNhspWeeklySnapshot: write_now requires options.outbox_id');
    const wr = await rpcTsfinWriteSnapshotsAndComplete(env, {
      rows: [{ outbox_id, timesheet_id: ts.timesheet_id, snapshot }]
    });
    return { ok: true, snapshot, write: wr };
  }

  return { ok: true, snapshot };
}


